{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.SPEED_ORDER_PROCESSING AS WITH op_dedup AS ( SELECT * FROM ( SELECT op.*, ROW_NUMBER() OVER ( PARTITION BY op.channel_order_number ORDER BY op.created_at DESC NULLS LAST ) AS rn FROM SNITCH_DB.MAPLEMONK.OMNI_ORDER_PROCESSING_META op WHERE op.branch_code IN ( \'14\',\'57\',\'68\',\'26\',\'42\',\'38\',\'142\',\'23\',\'49\',\'73\', \'82\',\'85\',\'90\',\'106\',\'114\',\'132\',\'103\',\'18\',\'134\',\'102\' ) ) x WHERE rn = 1 ), app_edd_dedup AS ( SELECT * FROM ( SELECT e.shopify_order_number, NULLIF(e.max_edd, \'\')::TIMESTAMP_NTZ AS app_edd, ROW_NUMBER() OVER ( PARTITION BY e.shopify_order_number ORDER BY e._airbyte_emitted_at DESC NULLS LAST, e._airbyte_normalized_at DESC NULLS LAST, NULLIF(e.max_edd, \'\')::TIMESTAMP_NTZ DESC NULLS LAST ) AS rn FROM SNITCH_DB.MAPLEMONK.APP_EDD_DATA e WHERE NULLIF(e.max_edd, \'\') IS NOT NULL ) x WHERE rn = 1 ), cp AS ( SELECT awb_number, MAX(assigned_date) AS assigned_date, MAX(pickup_date) AS pickup_date, MAX(delivery_date) AS delivery_date, MAX(outfordelivery_date) AS outfordelivery_date, MAX(out_for_delivery_attempts) AS out_for_delivery_attempts, MAX(status) AS status, MAX( CASE WHEN courier_partner ILIKE \'%blitz%\' OR courier_partner ILIKE \'%grow simplee%\' OR courier_partner ILIKE \'%growsimplee%\' THEN \'Blitz\' ELSE courier_partner END ) AS courier_partner, MAX(max_sla) AS max_sla, MAX(min_sla) AS min_sla, MAX(edd_cp) AS edd_cp, MAX(invoice_value) AS invoice_value, MAX(pincode) AS pincode, MAX(mapped_city) AS mapped_city, MAX(mapped_state) AS mapped_state, MAX(pickup_pincode) AS pickup_pincode, MAX(rto_mark_date) AS rto_mark_date FROM SNITCH_DB.MAPLEMONK.CP_1 WHERE mode = \'Forward\' GROUP BY awb_number ), draft AS ( SELECT op.awb, op.facility_switch, op.store_name, op.region, op.cluster, op.channel_order_number, op.branch_code, op.order_status, op.created_at, op.cancelled_at, NULLIF(op.cancelled_by, \'\') AS cancelled_by, NULLIF(op.cancelled_reason, \'\') AS cancelled_reason, op.pick_list_created_at, op.packed_at, op.manifested_at, op.dispatched_at, op.tat, op.sku, op.total_price, op.payment_method, op.category, op.allocation_rule_id, op.location, op.quantity, e.app_edd, c.assigned_date, c.pickup_date, c.delivery_date, c.outfordelivery_date, c.out_for_delivery_attempts, c.status, c.courier_partner, c.max_sla, c.min_sla, c.edd_cp, c.invoice_value, c.pincode, c.mapped_city, c.mapped_state, c.pickup_pincode, c.rto_mark_date FROM op_dedup op INNER JOIN app_edd_dedup e ON op.channel_order_number::TEXT = e.shopify_order_number::TEXT LEFT JOIN cp c ON op.awb::TEXT = c.awb_number::TEXT ), final AS ( SELECT d.*, d.created_at::DATE AS created_date_ist, d.created_at::TIME AS created_time_ist, DATEDIFF(day, d.created_at::DATE, d.app_edd::DATE) AS delivery_eta, DATEADD(minute, 690, d.app_edd::DATE) AS sdd_cutoff_ts, CASE WHEN d.created_at::TIME >= \'11:00:00\'::TIME AND d.created_at::TIME < \'17:00:00\'::TIME THEN DATEADD(minute, 1050, d.created_at::DATE) ELSE DATEADD(minute, 690, DATEADD(day, 1, d.created_at::DATE)) END AS ndd_cutoff_ts, CURRENT_TIMESTAMP()::TIMESTAMP_NTZ AS now_ist, COALESCE(d.pickup_date, d.outfordelivery_date) AS effective_handover_ts FROM draft d WHERE DATEDIFF(day, d.created_at::DATE, d.app_edd::DATE) IN (0, 1) AND LOWER(COALESCE(d.courier_partner, \'\')) NOT LIKE \'%hld%\' AND LOWER(COALESCE(d.courier_partner, \'\')) NOT LIKE \'%pidge%\' AND LOWER(COALESCE(d.courier_partner, \'\')) NOT LIKE \'%porter%\' ), status_tagging AS ( SELECT f.*, CASE WHEN f.delivery_eta = 0 THEN CASE WHEN f.manifested_at IS NOT NULL AND f.manifested_at <= f.sdd_cutoff_ts THEN \'SDD PROCESSING ADHERED\' WHEN f.manifested_at IS NULL AND f.now_ist <= f.sdd_cutoff_ts THEN \'SDD PROCESSING PENDING\' WHEN ( f.manifested_at IS NULL AND f.now_ist > f.sdd_cutoff_ts ) OR ( f.manifested_at IS NOT NULL AND f.manifested_at > f.sdd_cutoff_ts ) THEN \'SDD PROCESSING BREACHED\' END WHEN f.delivery_eta = 1 THEN CASE WHEN f.manifested_at IS NOT NULL AND f.manifested_at <= f.ndd_cutoff_ts THEN \'NDD PROCESSING ADHERED\' WHEN f.manifested_at IS NULL AND f.now_ist <= f.ndd_cutoff_ts THEN \'NDD PROCESSING PENDING\' WHEN ( f.manifested_at IS NULL AND f.now_ist > f.ndd_cutoff_ts ) OR ( f.manifested_at IS NOT NULL AND f.manifested_at > f.ndd_cutoff_ts ) THEN \'NDD PROCESSING BREACHED\' END END AS sla_status, CASE WHEN f.effective_handover_ts IS NULL THEN \'HANDOVER PENDING\' WHEN f.delivery_eta = 0 THEN CASE WHEN f.effective_handover_ts > f.sdd_cutoff_ts THEN \'HANDOVER BREACHED\' ELSE \'HANDOVER COMPLETED\' END WHEN f.delivery_eta = 1 THEN CASE WHEN f.effective_handover_ts > f.ndd_cutoff_ts THEN \'HANDOVER BREACHED\' ELSE \'HANDOVER COMPLETED\' END END AS handover_status, CASE WHEN f.delivery_date IS NULL THEN \'NOT DELIVERED\' WHEN f.delivery_date::DATE <= f.app_edd::DATE THEN \'DELIVERY ADHERED\' ELSE \'DELIVERY BREACHED\' END AS delivery_status FROM final f ) SELECT s.*, CASE WHEN s.sla_status ILIKE \'%BREACHED%\' THEN s.sla_status WHEN s.handover_status = \'HANDOVER BREACHED\' THEN s.handover_status WHEN s.delivery_status = \'DELIVERY BREACHED\' THEN s.delivery_status WHEN s.sla_status ILIKE \'%PENDING%\' THEN s.sla_status WHEN s.handover_status = \'HANDOVER PENDING\' THEN s.handover_status ELSE \'WITHIN TAT\' END AS rca FROM status_tagging s;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            